def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    S = data[1]
    T = data[2]

    to = [-1] * 26

    for s, t in zip(S, T):
        a = ord(s) - 97
        b = ord(t) - 97
        if to[a] == -1:
            to[a] = b
        elif to[a] != b:
            print(-1)
            return

    present = [x != -1 for x in to]
    present_count = sum(present)

    non_fixed = 0
    indeg = [0] * 26

    for i in range(26):
        if present[i]:
            if to[i] != i:
                non_fixed += 1
            indeg[to[i]] += 1

    state = [0] * 26
    unsupported_cycles = 0

    for i in range(26):
        if present[i] and state[i] == 0:
            path = []
            cur = i

            while present[cur] and state[cur] == 0:
                state[cur] = 1
                path.append(cur)
                cur = to[cur]

            if present[cur] and state[cur] == 1:
                v = cur
                length = 0
                supported = False

                while True:
                    length += 1
                    if indeg[v] > 1:
                        supported = True
                    v = to[v]
                    if v == cur:
                        break

                if length >= 2 and not supported:
                    unsupported_cycles += 1

            for v in path:
                state[v] = 2

    if present_count == 26 and non_fixed > 0:
        duplicate_target = any(indeg[i] > 1 for i in range(26))
        if not duplicate_target:
            print(-1)
            return

    print(non_fixed + unsupported_cycles)

