import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    out = []
    append = out.append

    for _ in range(t):
        R = int(data[idx])
        B = int(data[idx + 1])
        idx += 2

        if R + B < 2 or (R & 1) or (R == 0 and (B & 1)):
            append("No")
            continue

        if R == 0:
            append("Yes")
            if B == 2:
                append("B 1 1")
                append("B 2 2")
            else:
                m = B // 2
                u0 = 2 * m + 1
                u1 = u0 + 2
                v0 = 1
                v1 = 2 * m - 1

                u, v = u0, v0
                append(f"B {(u + v) // 2} {(u - v) // 2}")
                u, v = u1, v0
                append(f"B {(u + v) // 2} {(u - v) // 2}")

                for v in range(v0 + 2, v1 + 1, 2):
                    u = u1
                    append(f"B {(u + v) // 2} {(u - v) // 2}")

                append(f"B {(u0 + v1) // 2} {(u0 - v1) // 2}")

                for v in range(v1 - 2, v0 + 1, -2):
                    u = u0
                    append(f"B {(u + v) // 2} {(u - v) // 2}")
            continue

        if B == 0:
            append("Yes")
            w = R // 2
            for c in range(1, w + 1):
                append(f"R 1 {c}")
            for c in range(w, 0, -1):
                append(f"R 2 {c}")
            continue

        append("Yes")

        if B & 1:
            k = (B - 1) // 2
            m = R // 2
            off = max(k, m) + 5

            for y in range(k + 1):
                append(f"B {y + off} {off - y}")
            for y in range(k, 0, -1):
                append(f"B {y + 1 + off} {1 - y + off}")

            for c in range(1, m + 1):
                append(f"R {1 + off} {c + off}")
            for c in range(m, 0, -1):
                append(f"R {off} {c + off}")

        else:
            k = B // 2
            m = R // 2
            off = max(k, m) + 5

            for y in range(k + 1):
                append(f"B {y + off} {off - y}")
            for y in range(k, 1, -1):
                append(f"B {y + 1 + off} {1 - y + off}")

            for c in range(m):
                append(f"R {2 + off} {c + off}")
            append(f"R {1 + off} {m - 1 + off}")
            for c in range(m - 1, 0, -1):
                append(f"R {off} {c + off}")

    if out:
        sys.stdout.write("\n".join(out) + "\n")

