class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        if not queries:
            return 0

        max_r = max(r for _, r in queries)

        # powers[i] = 4^i
        powers = [1]
        while powers[-1] <= max_r:
            powers.append(powers[-1] * 4)

        # prefix_full[i] = sum of operations needed for all x in [1, 4^i - 1]
        prefix_full = [0] * len(powers)
        for i in range(1, len(powers)):
            prefix_full[i] = prefix_full[i - 1] + (powers[i] - powers[i - 1]) * i

        def prefix_sum(n: int) -> int:
            """Sum of operations needed for all integers from 1 to n."""
            if n <= 0:
                return 0
            idx = bisect_right(powers, n) - 1
            return prefix_full[idx] + (n - powers[idx] + 1) * (idx + 1)

        ans = 0
        for l, r in queries:
            total = prefix_sum(r) - prefix_sum(l - 1)
            max_single = bisect_right(powers, r)  # operations needed for r
            ans += max(max_single, (total + 1) // 2)

        return ans

import sys

def main():
    s = sys.stdin.buffer.read().strip()
    if not s:
        return

    n = len(s)
    p = s[::-1]

    # Prefix function for p (the reversed string)
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        c = p[i]
        while j and c != p[j]:
            j = pi[j - 1]
        if c == p[j]:
            j += 1
        pi[i] = j

    # KMP scan: longest prefix of p that is a suffix of s
    q = 0
    for c in s:
        while q and c != p[q]:
            q = pi[q - 1]
        if c == p[q]:
            q += 1

    # q is the length of the longest palindromic suffix of s
    ans = s + s[:n - q][::-1]
    sys.stdout.buffer.write(ans + b'\n')

if __name__ == "__main__":
    main()

