class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        children = [{}]
        count = [0]
        depth = [0]
        terminal = [0] * n

        for i, word in enumerate(words):
            node = 0
            for ch in word:
                cmap = children[node]
                if cmap is None:
                    cmap = {}
                    children[node] = cmap
                nxt = cmap.get(ch)
                if nxt is None:
                    nxt = len(children)
                    children.append(None)
                    count.append(0)
                    depth.append(depth[node] + 1)
                    cmap[ch] = nxt
                node = nxt
                count[node] += 1
            terminal[i] = node

        m = len(children)
        best = [0] * m

        # best[u] = deepest prefix in subtree(u) whose total count is at least k.
        for node in range(m - 1, -1, -1):
            cur = depth[node] if count[node] >= k else 0
            cmap = children[node]
            if cmap:
                for child in cmap.values():
                    if best[child] > cur:
                        cur = best[child]
            best[node] = cur

        need_on_path = k + 1
        stack = [(0, 0, 0)]  # node, best outside path, best ancestor with count >= k+1

        while stack:
            node, up_best, path_best = stack.pop()

            top1 = 0
            top2 = 0
            top1_child = -1
            cmap = children[node]
            if cmap:
                for child in cmap.values():
                    val = best[child]
                    if val > top1:
                        top2 = top1
                        top1 = val
                        top1_child = child
                    elif val > top2:
                        top2 = val

            # top1 is the best marked prefix strictly below this node (descendant).
            ans = up_best if up_best > top1 else top1
            if path_best > ans:
                ans = path_best
            best[node] = ans  # reuse best[] to store the final answer for this node

            if cmap:
                for child in cmap.values():
                    sibling_best = top2 if child == top1_child else top1
                    child_up = up_best if up_best > sibling_best else sibling_best

                    child_path = path_best
                    if count[child] >= need_on_path and depth[child] > child_path:
                        child_path = depth[child]

                    stack.append((child, child_up, child_path))

        return [best[node] for node in terminal]

