import math


def integer_cuberoot(n: int) -> int:
    lo, hi = 0, 1
    while hi * hi * hi <= n:
        hi *= 2

    while hi - lo > 1:
        mid = (lo + hi) // 2
        if mid * mid * mid <= n:
            lo = mid
        else:
            hi = mid

    return lo


def main() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    limit = integer_cuberoot(N)
    isqrt = math.isqrt

    for d in range(1, limit + 1):
        if N % d != 0:
            continue

        m = N // d

        # Need 3*y^2 + 3*d*y + d^2 = m.
        # Discriminant D = 12*m - 3*d^2 = 3*(4*m - d^2).
        t = 4 * m - d * d
        if t <= 0:
            continue

        D = 3 * t
        s = isqrt(D)

        if s * s != D:
            continue

        three_d = 3 * d
        if s <= three_d:
            continue

        diff = s - three_d
        if diff % 6 != 0:
            continue

        y = diff // 6
        x = y + d

        if x * x * x - y * y * y == N:
            print(x, y)
            return

    print(-1)


