import sys

def solve():
    input = sys.stdin.buffer.readline
    first = input().split()
    if not first:
        return

    N = int(first[0])
    K = int(first[1])
    M = N * K

    if K == 1:
        print("Yes")
        return

    adj = [[] for _ in range(M)]
    for _ in range(M - 1):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    parent = [-1] * M
    parent[0] = -2
    order = []
    stack = [0]

    while stack:
        v = stack.pop()
        order.append(v)
        for to in adj[v]:
            if to == parent[v]:
                continue
            if parent[to] != -1:
                continue
            parent[to] = v
            stack.append(to)

    if len(order) != M:
        print("No")
        return

    rem = [0] * M
    ok = True
    km1 = K - 1

    for v in reversed(order):
        cnt = 0
        sm = 0
        r = 1

        for to in adj[v]:
            if parent[to] == v:
                cr = rem[to]
                r += cr
                if cr:
                    cnt += 1
                    sm += cr

        r %= K
        rem[v] = r

        if r != 0:
            if cnt > 1:
                ok = False
            elif cnt == 1:
                if r != sm + 1:
                    ok = False
            else:
                if r != 1:
                    ok = False
        else:
            if cnt == 0 or cnt > 2:
                ok = False
            elif sm != km1:
                ok = False

    if rem[0] != 0:
        ok = False

    print("Yes" if ok else "No")

