class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        if m == 0:
            return n * (n + 1) // 2

        buckets = [[] for _ in range(n + 1)]
        xs = [0] * m

        for i, (a, b) in enumerate(conflictingPairs):
            if a < b:
                x, y = a, b
            else:
                x, y = b, a
            xs[i] = x
            buckets[y].append(i)

        cnt = [0] * (n + 1)
        rep = [-1] * (n + 1)
        gain = [0] * m

        top1 = 0
        top2 = 0
        total = 0

        for r in range(1, n + 1):
            for idx in buckets[r]:
                x = xs[idx]
                c = cnt[x]

                if c == 0:
                    cnt[x] = 1
                    rep[x] = idx

                    if x > top1:
                        top2 = top1
                        top1 = x
                    elif x > top2:
                        top2 = x

                elif c == 1:
                    cnt[x] = 2
                    rep[x] = -1

                else:
                    cnt[x] = c + 1

            total += r - top1

            if top1 != 0 and cnt[top1] == 1:
                gain[rep[top1]] += top1 - top2

        return total + max(gain)

import sys

def solve():
    input = sys.stdin.buffer.readline
    first = input().split()
    if not first:
        return

    N = int(first[0])
    M = int(first[1])

    adj = [[] for _ in range(N + 1)]
    max_z = 0

    for _ in range(M):
        x, y, z = map(int, input().split())
        adj[x].append((y, z))
        adj[y].append((x, z))
        if z > max_z:
            max_z = z

    dist = [-1] * (N + 1)
    ans = [0] * (N + 1)
    max_bit = max(1, max_z.bit_length())

    for start in range(1, N + 1):
        if dist[start] != -1:
            continue

        dist[start] = 0
        stack = [start]
        comp = []

        while stack:
            v = stack.pop()
            comp.append(v)
            dv = dist[v]

            for to, w in adj[v]:
                nd = dv ^ w
                if dist[to] == -1:
                    dist[to] = nd
                    stack.append(to)
                elif dist[to] != nd:
                    sys.stdout.write("-1\n")
                    return

        size = len(comp)

        if size == 1:
            ans[comp[0]] = dist[comp[0]]
            continue

        cnt = [0] * max_bit

        for v in comp:
            d = dist[v]
            k = 0
            while d:
                if d & 1:
                    cnt[k] += 1
                d >>= 1
                k += 1

        t = 0
        for k, c in enumerate(cnt):
            if size - c < c:
                t |= 1 << k

        for v in comp:
            ans[v] = dist[v] ^ t

    sys.stdout.write(" ".join(map(str, ans[1:])) + "\n")

