class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        p_vals = [ord(ch) - 97 for ch in str2]

        # fixed[pos] = -1 means free, otherwise it is forced by a 'T' constraint.
        fixed = [-1] * L
        f_end = [False] * L

        # Apply all 'T' constraints and mark ends of 'F' windows.
        for i, flag in enumerate(str1):
            if flag == 'T':
                pos = i
                for val in p_vals:
                    old = fixed[pos]
                    if old == -1:
                        fixed[pos] = val
                    elif old != val:
                        return ""
                    pos += 1
            else:
                f_end[i + m - 1] = True

        fixed_count = L - fixed.count(-1)

        # Prefix function for KMP.
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and p_vals[i] != p_vals[j]:
                j = pi[j - 1]
            if p_vals[i] == p_vals[j]:
                j += 1
            pi[i] = j

        fallback = pi[m - 1]

        # Build KMP automaton for states 0..m.
        go = [[0] * 26 for _ in range(m + 1)]
        for s in range(m + 1):
            for c in range(26):
                if s < m and c == p_vals[s]:
                    go[s][c] = s + 1
                elif s == 0:
                    go[s][c] = 0
                else:
                    go[s][c] = go[pi[s - 1]][c]

        bit = [1 << i for i in range(m)]
        all_mask = (1 << m) - 1

        # nexts[c][s] is the next state after reading char c from state s.
        # If a full match happens, we immediately fall back to pi[m-1].
        nexts = [[0] * m for _ in range(26)]
        match_mask = [0] * 26

        # For free positions:
        # mask_all[s] = possible next states using any character.
        # mask_nonmatch[s] = possible next states using a character that does NOT complete str2.
        mask_all = [0] * m
        mask_nonmatch = [0] * m

        for c in range(26):
            mm = 0
            nexts_c = nexts[c]
            for s in range(m):
                k = go[s][c]
                if k == m:
                    ns = fallback
                    mm |= bit[s]
                else:
                    ns = k

                nexts_c[s] = ns
                nb = bit[ns]
                mask_all[s] |= nb
                if k != m:
                    mask_nonmatch[s] |= nb

            match_mask[c] = mm

        del go

        chars = [chr(97 + i) for i in range(26)]

        # If every position is fixed, just verify the F constraints.
        if fixed_count == L:
            state = 0
            res = []
            for pos in range(L):
                c = fixed[pos]
                if c < 0:
                    return ""
                if f_end[pos] and (match_mask[c] & bit[state]):
                    return ""
                res.append(chars[c])
                state = nexts[c][state]
            return "".join(res)

        # If at an F-end and all future states are acceptable, every state can choose
        # some non-matching character (alphabet size is 26, at most one char matches).
        free_F_all_possible = all(mask != 0 for mask in mask_nonmatch)

        # Pairs for fast DP transitions.
        pairs_all = [(mask_all[s], bit[s]) for s in range(m)]
        pairs_nonmatch = [(mask_nonmatch[s], bit[s]) for s in range(m)]

        fixed_pairs_all = [[] for _ in range(26)]
        fixed_pairs_nonmatch = [[] for _ in range(26)]

        for c in range(26):
            fp_all = fixed_pairs_all[c]
            fp_non = fixed_pairs_nonmatch[c]
            nexts_c = nexts[c]
            mm = match_mask[c]
            for s in range(m):
                nb = bit[nexts_c[s]]
                sb = bit[s]
                fp_all.append((nb, sb))
                if not (mm & sb):
                    fp_non.append((nb, sb))

        # good[pos] is a bitmask of automaton states before position pos
        # from which the suffix pos..L-1 can be completed.
        good = [0] * (L + 1)
        good[L] = all_mask

        for pos in range(L - 1, -1, -1):
            ng = good[pos + 1]
            fc = fixed[pos]
            fe = f_end[pos]

            # Fast path when every next state is acceptable.
            if ng == all_mask:
                if fc == -1:
                    if (not fe) or free_F_all_possible:
                        good[pos] = all_mask
                        continue
                elif not fe:
                    good[pos] = all_mask
                    continue
                else:
                    bits = all_mask & ~match_mask[fc]
                    if bits == 0:
                        return ""
                    good[pos] = bits
                    continue

            bits = 0
            if fc == -1:
                pairs = pairs_nonmatch if fe else pairs_all
                for mask, sb in pairs:
                    if mask & ng:
                        bits |= sb
            else:
                pairs = fixed_pairs_nonmatch[fc] if fe else fixed_pairs_all[fc]
                for nb, sb in pairs:
                    if ng & nb:
                        bits |= sb

            if bits == 0:
                return ""
            good[pos] = bits

        if (good[0] & 1) == 0:
            return ""

        # Greedily construct the lexicographically smallest valid string.
        res = []
        state = 0

        for pos in range(L):
            fe = f_end[pos]
            ng = good[pos + 1]
            s_bit = bit[state]
            fc = fixed[pos]

            if fc != -1:
                if fe and (match_mask[fc] & s_bit):
                    return ""
                ns = nexts[fc][state]
                if not (ng & bit[ns]):
                    return ""
                res.append(chars[fc])
                state = ns
            else:
                for c in range(26):
                    if fe and (match_mask[c] & s_bit):
                        continue
                    ns = nexts[c][state]
                    if ng & bit[ns]:
                        res.append(chars[c])
                        state = ns
                        break
                else:
                    return ""

        return "".join(res)

