class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        if k <= 0:
            return []

        # Counts larger than k are equivalent for unranking.
        INF = k + 1

        def cap_mul(a: int, b: int) -> int:
            if a == 0 or b == 0:
                return 0
            if a > INF // b:
                return INF
            return a * b

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = cap_mul(fact[i - 1], i)

        def count(o: int, e: int, prev: int) -> int:
            """
            Number of valid completions with:
            - o remaining odd numbers
            - e remaining even numbers
            - prev parity of the last placed number:
              1 = odd, 0 = even, -1 = none
            """
            if o < 0 or e < 0:
                return 0
            if o + e == 0:
                return 1

            if prev == -1:
                if o == e:
                    patterns = 2
                elif o == e + 1:
                    patterns = 1
                elif e == o + 1:
                    patterns = 1
                else:
                    patterns = 0
            else:
                length = o + e
                start = 1 - prev  # next parity is forced

                if start == 1:  # starts with odd
                    need_o = (length + 1) // 2
                    need_e = length // 2
                else:           # starts with even
                    need_o = length // 2
                    need_e = (length + 1) // 2

                patterns = 1 if o == need_o and e == need_e else 0

            if patterns == 0:
                return 0

            res = fact[o]
            res = cap_mul(res, fact[e])
            if patterns == 2:
                res = cap_mul(res, 2)
            return res

        odd_count = (n + 1) // 2
        even_count = n // 2

        if count(odd_count, even_count, -1) < k:
            return []

        used = [False] * (n + 1)
        ans = []
        rem_o, rem_e = odd_count, even_count
        prev = -1

        for _ in range(n):
            chosen = -1

            for x in range(1, n + 1):
                if used[x]:
                    continue

                parity = x & 1

                if prev != -1 and parity == prev:
                    cnt = 0
                elif parity == 1:
                    cnt = count(rem_o - 1, rem_e, 1)
                else:
                    cnt = count(rem_o, rem_e - 1, 0)

                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    break

            if chosen == -1:
                return []

            ans.append(chosen)
            used[chosen] = True

            if chosen & 1:
                rem_o -= 1
            else:
                rem_e -= 1

            prev = chosen & 1

        return ans

