class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        INF = 10**30

        # Actual coordinates per assigned side:
        # 0: bottom, coordinate x
        # 1: right,  coordinate y
        # 2: top,    coordinate x
        # 3: left,   coordinate y
        actual = [[], [], [], []]

        # Clockwise coordinates per side, used for the fast d <= side solver.
        # 0: bottom, t = x             (BL -> BR)
        # 1: right,  t = y             (BR -> TR)
        # 2: top,    t = side - x      (TR -> TL)
        # 3: left,   t = side - y      (TL -> BL)
        clockwise = [[], [], [], []]

        for x, y in points:
            if y == 0:
                actual[0].append(x)
                clockwise[0].append(x)
            elif x == s:
                actual[1].append(y)
                clockwise[1].append(y)
            elif y == s:
                actual[2].append(x)
                clockwise[2].append(s - x)
            else:
                actual[3].append(y)
                clockwise[3].append(s - y)

        for i in range(4):
            actual[i].sort()
            clockwise[i].sort()

        def point_on_side(sd: int, v: int):
            if sd == 0:
                return (v, 0)
            if sd == 1:
                return (s, v)
            if sd == 2:
                return (v, s)
            return (0, v)

        def dist_two(sd1: int, v1: int, sd2: int, v2: int) -> int:
            x1, y1 = point_on_side(sd1, v1)
            x2, y2 = point_on_side(sd2, v2)
            return abs(x1 - x2) + abs(y1 - y2)

        # ---------- Fast exact solver for d <= side ----------
        # Only adjacent-side constraints are non-trivial.
        # Opposite sides are automatically at distance at least side.

        class SideData:
            __slots__ = ("arr", "n", "up", "U", "maxc", "s", "d", "cache")

            def __init__(self, arr, up, U, maxc, s, d):
                self.arr = arr
                self.n = len(arr)
                self.up = up
                self.U = U
                self.maxc = maxc
                self.s = s
                self.d = d
                self.cache = {}

            def eval_f(self, c: int, a: int) -> int:
                """
                For this side and chosen count c:
                a = required lower bound on left endpoint distance.
                Returns required lower bound on the next side's left endpoint:
                    max(0, d - max_right_distance(a))
                INF if impossible.
                """
                if c == 0:
                    return 0
                if c > self.maxc:
                    return INF
                if a < 0:
                    a = 0
                if a > self.U[c]:
                    return INF

                key = (c, a)
                cached = self.cache.get(key)
                if cached is not None:
                    return cached

                arr = self.arr
                n = self.n
                idx = bisect_left(arr, a)
                if idx >= n:
                    self.cache[key] = INF
                    return INF

                steps = c - 1
                bit = 0
                cur = idx
                up = self.up
                while steps and cur != -1:
                    if steps & 1:
                        cur = up[bit][cur]
                    steps >>= 1
                    bit += 1

                if cur == -1:
                    self.cache[key] = INF
                    return INF

                g = self.s - arr[cur]       # maximum possible right distance
                res = self.d - g
                if res < 0:
                    res = 0
                self.cache[key] = res
                return res

        def build_side_data(arr: List[int], d: int) -> SideData:
            n = len(arr)
            max_possible = min(k, n)

            nxt = [-1] * n
            j = 0
            for i in range(n):
                if j <= i:
                    j = i + 1
                target = arr[i] + d
                while j < n and arr[j] < target:
                    j += 1
                nxt[i] = j if j < n else -1

            LOG = 5  # 2^5 > 25
            up = [nxt]
            for _ in range(1, LOG):
                prev = up[-1]
                cur = [-1] * n
                for i in range(n):
                    mid = prev[i]
                    cur[i] = prev[mid] if mid != -1 else -1
                up.append(cur)

            U = [s] * (max_possible + 1)
            maxc = 0
            for c in range(1, max_possible + 1):
                idx = n - 1
                ok = True
                for _ in range(c - 1):
                    if d == 0:
                        idx -= 1
                    else:
                        idx = bisect_right(arr, arr[idx] - d) - 1
                    if idx < 0:
                        ok = False
                        break
                if ok:
                    U[c] = arr[idx]
                    maxc = c
                else:
                    U[c] = -1

            return SideData(arr, up, U, maxc, s, d)

        def check_fast(d: int) -> bool:
            if d == 0:
                return True

            datas = [build_side_data(clockwise[i], d) for i in range(4)]
            maxc = [min(k, datas[i].maxc) for i in range(4)]
            if sum(maxc) < k:
                return False

            c0_max = maxc[0]
            c1_max = maxc[1]
            c2_max = maxc[2]
            c3_max = maxc[3]

            for c0 in range(c0_max + 1):
                rem0 = k - c0
                if rem0 < 0:
                    break
                for c1 in range(min(c1_max, rem0) + 1):
                    rem1 = rem0 - c1
                    for c2 in range(min(c2_max, rem1) + 1):
                        c3 = rem1 - c2
                        if c3 < 0 or c3 > c3_max:
                            continue

                        cnt = (c0, c1, c2, c3)

                        # If all four sides are used, the adjacent constraints form
                        # a directed cycle. A positive continuous drift is impossible.
                        if c0 and c1 and c2 and c3:
                            if k * d > 4 * s:
                                continue

                        out = [[], [], [], []]
                        for i in range(4):
                            j = (i + 1) & 3
                            if cnt[i] and cnt[j]:
                                out[i].append(j)

                        left = [0, 0, 0, 0]
                        q = deque(i for i in range(4) if cnt[i] and out[i])
                        inq = [False] * 4
                        ok = True

                        while q and ok:
                            i = q.popleft()
                            inq[i] = False
                            val = datas[i].eval_f(cnt[i], left[i])
                            if val >= INF:
                                ok = False
                                break
                            for j in out[i]:
                                if val > left[j]:
                                    left[j] = val
                                    if left[j] > datas[j].U[cnt[j]]:
                                        ok = False
                                        break
                                    if out[j] and not inq[j]:
                                        q.append(j)
                                        inq[j] = True
                            if not ok:
                                break

                        if not ok:
                            continue

                        good = True
                        for i in range(4):
                            if cnt[i] and left[i] > datas[i].U[cnt[i]]:
                                good = False
                                break
                        if good:
                            return True

            return False

        # ---------- Exact solver for d > side, only needed when k <= 4 ----------
        # Then at most one point can be chosen from each assigned side.

        def merge_intervals(intervals):
            if not intervals:
                return tuple()
            intervals = sorted(intervals)
            res = []
            for l, r in intervals:
                if l > r:
                    continue
                if not res or l > res[-1][1] + 1:
                    res.append([l, r])
                else:
                    if r > res[-1][1]:
                        res[-1][1] = r
            return tuple((l, r) for l, r in res)

        def intersect_intervals(A, B):
            i = j = 0
            res = []
            while i < len(A) and j < len(B):
                l = max(A[i][0], B[j][0])
                r = min(A[i][1], B[j][1])
                if l <= r:
                    res.append((l, r))
                if A[i][1] < B[j][1]:
                    i += 1
                else:
                    j += 1
            return tuple(res)

        def allowed_intervals_from_point(src_sd: int, v: int, tgt_sd: int, d: int):
            """
            For a fixed point on src_sd, return intervals of coordinate u on tgt_sd
            such that Manhattan distance >= d.
            """
            px, py = point_on_side(src_sd, v)

            if tgt_sd == 0:
                def dist(u):
                    return abs(px - u) + py
                u0 = min(max(px, 0), s)
            elif tgt_sd == 1:
                def dist(u):
                    return abs(px - s) + abs(py - u)
                u0 = min(max(py, 0), s)
            elif tgt_sd == 2:
                def dist(u):
                    return abs(px - u) + abs(py - s)
                u0 = min(max(px, 0), s)
            else:
                def dist(u):
                    return px + abs(py - u)
                u0 = min(max(py, 0), s)

            if dist(u0) >= d:
                return ((0, s),)

            res = []

            # Left of the closest point: distance decreases as u approaches u0.
            if u0 > 0 and dist(0) >= d:
                lo, hi = 0, u0  # dist(lo) >= d, dist(hi) < d
                while lo + 1 < hi:
                    mid = (lo + hi) // 2
                    if dist(mid) >= d:
                        lo = mid
                    else:
                        hi = mid
                res.append((0, lo))

            # Right of the closest point: distance increases as u moves away.
            if u0 < s and dist(s) >= d:
                lo, hi = u0, s  # dist(lo) < d, dist(hi) >= d
                while lo + 1 < hi:
                    mid = (lo + hi) // 2
                    if dist(mid) >= d:
                        hi = mid
                    else:
                        lo = mid
                res.append((hi, s))

            return merge_intervals(res)

        def get_min_point(arr, intervals):
            for l, r in intervals:
                idx = bisect_left(arr, l)
                if idx < len(arr) and arr[idx] <= r:
                    return arr[idx]
            return None

        def get_max_point(arr, intervals):
            for l, r in reversed(intervals):
                idx = bisect_right(arr, r) - 1
                if idx >= 0 and arr[idx] >= l:
                    return arr[idx]
            return None

        def count_points(arr, intervals):
            cnt = 0
            for l, r in intervals:
                cnt += bisect_right(arr, r) - bisect_left(arr, l)
            return cnt

        def get_points_in_intervals(arr, intervals):
            pts = []
            for l, r in intervals:
                left = bisect_left(arr, l)
                right = bisect_right(arr, r)
                pts.extend(arr[left:right])
            return pts

        def get_kth_point(arr, intervals, kth):
            for l, r in intervals:
                left = bisect_left(arr, l)
                right = bisect_right(arr, r)
                cnt = right - left
                if kth < cnt:
                    return arr[left + kth]
                kth -= cnt
            return None

        def propagate_gt_s(intervals, sd_list, d):
            m = len(sd_list)
            ivs = [list(iv) for iv in intervals]
            q = deque(range(m))
            inq = [True] * m

            while q:
                i = q.popleft()
                inq[i] = False
                old = ivs[i]
                new = old
                si = sd_list[i]

                for jj in range(m):
                    if jj == i:
                        continue
                    sj = sd_list[jj]
                    arrj = actual[sj]

                    mn = get_min_point(arrj, ivs[jj])
                    if mn is None:
                        return None
                    mx = get_max_point(arrj, ivs[jj])

                    allowed = []
                    allowed.extend(allowed_intervals_from_point(sj, mn, si, d))
                    if mx != mn:
                        allowed.extend(allowed_intervals_from_point(sj, mx, si, d))
                    allowed = merge_intervals(allowed)

                    new = intersect_intervals(new, allowed)
                    if not new:
                        return None

                if new != old:
                    ivs[i] = list(new)
                    for jj in range(m):
                        if jj != i and not inq[jj]:
                            q.append(jj)
                            inq[jj] = True

            return tuple(tuple(iv) for iv in ivs)

        def solve_subset_gt_s(sd_list, d):
            m = len(sd_list)
            init = tuple(((0, s),) for _ in range(m))
            memo = {}

            def search(intervals):
                prop = propagate_gt_s(intervals, sd_list, d)
                if prop is None:
                    return False

                key = prop
                if key in memo:
                    return memo[key]

                mins = []
                maxs = []
                counts = []

                for idx, sd in enumerate(sd_list):
                    arr = actual[sd]
                    mn = get_min_point(arr, prop[idx])
                    if mn is None:
                        memo[key] = False
                        return False
                    mx = get_max_point(arr, prop[idx])
                    cnt = count_points(arr, prop[idx])
                    mins.append(mn)
                    maxs.append(mx)
                    counts.append(cnt)

                # Try extreme candidates first; often enough.
                choices = []
                for idx in range(m):
                    if mins[idx] == maxs[idx]:
                        choices.append((mins[idx],))
                    else:
                        choices.append((mins[idx], maxs[idx]))

                for combo in product(*choices):
                    ok = True
                    for a in range(m):
                        for b in range(a + 1, m):
                            if dist_two(sd_list[a], combo[a], sd_list[b], combo[b]) < d:
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        memo[key] = True
                        return True

                if m == 1:
                    memo[key] = True
                    return True

                if m == 2:
                    # For two sets, maximum distance is attained by extremes.
                    memo[key] = False
                    return False

                # Choose the most constrained side.
                pick = min(range(m), key=lambda x: counts[x])
                if counts[pick] == 0:
                    memo[key] = False
                    return False

                if counts[pick] == 1:
                    v = mins[pick]
                    nxt = list(prop)
                    nxt[pick] = ((v, v),)
                    res = search(tuple(nxt))
                    memo[key] = res
                    return res

                # Small domain: enumerate exactly.
                if counts[pick] <= 30:
                    pts = get_points_in_intervals(actual[sd_list[pick]], prop[pick])
                    for v in pts:
                        nxt = list(prop)
                        nxt[pick] = ((v, v),)
                        if search(tuple(nxt)):
                            memo[key] = True
                            return True
                    memo[key] = False
                    return False

                # Large domain: split by median candidate.
                med = get_kth_point(actual[sd_list[pick]], prop[pick], counts[pick] // 2)
                left_iv = intersect_intervals(prop[pick], ((0, med),))
                right_iv = intersect_intervals(prop[pick], ((med + 1, s),))

                if left_iv:
                    nxt = list(prop)
                    nxt[pick] = left_iv
                    if search(tuple(nxt)):
                        memo[key] = True
                        return True

                if right_iv:
                    nxt = list(prop)
                    nxt[pick] = right_iv
                    if search(tuple(nxt)):
                        memo[key] = True
                        return True

                memo[key] = False
                return False

            return search(init)

        def check_gt_s(d: int) -> bool:
            if k > 4:
                return False
            for comb in combinations(range(4), k):
                if any(not actual[i] for i in comb):
                    continue
                if solve_subset_gt_s(list(comb), d):
                    return True
            return False

        def check(d: int) -> bool:
            if d == 0:
                return True
            if d <= s:
                return check_fast(d)
            return check_gt_s(d)

        # If k >= 5, by pigeonhole two chosen points lie on the same side,
        # so the answer cannot exceed side.
        low = 0
        high = 2 * s if k <= 4 else s

        while low < high:
            mid = (low + high + 1) // 2
            if check(mid):
                low = mid
            else:
                high = mid - 1

        return low

from typing import List
from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        N = n * m

        flat = bytearray()
        for row in grid:
            flat.extend(row)

        if 1 not in flat:
            return 0
        if n == 1 or m == 1:
            return 1
        if 2 not in flat:
            return 1

        del grid

        n1 = n - 1
        m1 = m - 1

        # straight[d][0]: longest straight alternating segment starting with expected value 2
        # straight[d][1]: longest straight alternating segment starting with expected value 0
        # Directions in clockwise order:
        # 0: SE (1, 1), 1: SW (1, -1), 2: NW (-1, -1), 3: NE (-1, 1)
        straight = [[array('H', [0]) * N for _ in range(2)] for __ in range(4)]

        ir_desc = range(n1, -1, -1)
        ir_asc = range(n)
        jr_desc = range(m1, -1, -1)
        jr_asc = range(m)

        # Direction 0: SE, next index step = m + 1
        arr2, arr0 = straight[0]
        step = m + 1
        for i in ir_desc:
            base = i * m
            for j in jr_desc:
                idx = base + j
                val = flat[idx]
                if val == 2:
                    if i < n1 and j < m1:
                        arr2[idx] = 1 + arr0[idx + step]
                    else:
                        arr2[idx] = 1
                elif val == 0:
                    if i < n1 and j < m1:
                        arr0[idx] = 1 + arr2[idx + step]
                    else:
                        arr0[idx] = 1

        # Direction 1: SW, next index step = m - 1
        arr2, arr0 = straight[1]
        step = m - 1
        for i in ir_desc:
            base = i * m
            for j in jr_asc:
                idx = base + j
                val = flat[idx]
                if val == 2:
                    if i < n1 and j > 0:
                        arr2[idx] = 1 + arr0[idx + step]
                    else:
                        arr2[idx] = 1
                elif val == 0:
                    if i < n1 and j > 0:
                        arr0[idx] = 1 + arr2[idx + step]
                    else:
                        arr0[idx] = 1

        # Direction 2: NW, next index step = -m - 1
        arr2, arr0 = straight[2]
        step = -m - 1
        for i in ir_asc:
            base = i * m
            for j in jr_asc:
                idx = base + j
                val = flat[idx]
                if val == 2:
                    if i > 0 and j > 0:
                        arr2[idx] = 1 + arr0[idx + step]
                    else:
                        arr2[idx] = 1
                elif val == 0:
                    if i > 0 and j > 0:
                        arr0[idx] = 1 + arr2[idx + step]
                    else:
                        arr0[idx] = 1

        # Direction 3: NE, next index step = -m + 1
        arr2, arr0 = straight[3]
        step = -m + 1
        for i in ir_asc:
            base = i * m
            for j in jr_desc:
                idx = base + j
                val = flat[idx]
                if val == 2:
                    if i > 0 and j < m1:
                        arr2[idx] = 1 + arr0[idx + step]
                    else:
                        arr2[idx] = 1
                elif val == 0:
                    if i > 0 and j < m1:
                        arr0[idx] = 1 + arr2[idx + step]
                    else:
                        arr0[idx] = 1

        ans = 1

        # DP with one clockwise turn still available.
        # cur2/cur0 are recomputed for each initial direction.

        # Initial direction 0: SE, clockwise turn to SW.
        cur2 = [0] * N
        cur0 = [0] * N
        turn0 = straight[1][1]
        turn2 = straight[1][0]
        step = m + 1
        tstep = m - 1
        for i in ir_desc:
            base = i * m
            for j in jr_desc:
                idx = base + j
                val = flat[idx]
                if val == 2:
                    best = 1
                    if i < n1 and j < m1:
                        b = 1 + cur0[idx + step]
                        if b > best:
                            best = b
                    if i < n1 and j > 0:
                        b = 1 + turn0[idx + tstep]
                        if b > best:
                            best = b
                    cur2[idx] = best
                    if i > 0 and j > 0 and flat[idx - step] == 1:
                        cand = best + 1
                        if cand > ans:
                            ans = cand
                elif val == 0:
                    best = 1
                    if i < n1 and j < m1:
                        b = 1 + cur2[idx + step]
                        if b > best:
                            best = b
                    if i < n1 and j > 0:
                        b = 1 + turn2[idx + tstep]
                        if b > best:
                            best = b
                    cur0[idx] = best

        # Initial direction 1: SW, clockwise turn to NW.
        cur2 = [0] * N
        cur0 = [0] * N
        turn0 = straight[2][1]
        turn2 = straight[2][0]
        step = m - 1
        tstep = -m - 1
        for i in ir_desc:
            base = i * m
            for j in jr_asc:
                idx = base + j
                val = flat[idx]
                if val == 2:
                    best = 1
                    if i < n1 and j > 0:
                        b = 1 + cur0[idx + step]
                        if b > best:
                            best = b
                    if i > 0 and j > 0:
                        b = 1 + turn0[idx + tstep]
                        if b > best:
                            best = b
                    cur2[idx] = best
                    if i > 0 and j < m1 and flat[idx - step] == 1:
                        cand = best + 1
                        if cand > ans:
                            ans = cand
                elif val == 0:
                    best = 1
                    if i < n1 and j > 0:
                        b = 1 + cur2[idx + step]
                        if b > best:
                            best = b
                    if i > 0 and j > 0:
                        b = 1 + turn2[idx + tstep]
                        if b > best:
                            best = b
                    cur0[idx] = best

        # Initial direction 2: NW, clockwise turn to NE.
        cur2 = [0] * N
        cur0 = [0] * N
        turn0 = straight[3][1]
        turn2 = straight[3][0]
        step = -m - 1
        tstep = -m + 1
        for i in ir_asc:
            base = i * m
            for j in jr_asc:
                idx = base + j
                val = flat[idx]
                if val == 2:
                    best = 1
                    if i > 0 and j > 0:
                        b = 1 + cur0[idx + step]
                        if b > best:
                            best = b
                    if i > 0 and j < m1:
                        b = 1 + turn0[idx + tstep]
                        if b > best:
                            best = b
                    cur2[idx] = best
                    if i < n1 and j < m1 and flat[idx - step] == 1:
                        cand = best + 1
                        if cand > ans:
                            ans = cand
                elif val == 0:
                    best = 1
                    if i > 0 and j > 0:
                        b = 1 + cur2[idx + step]
                        if b > best:
                            best = b
                    if i > 0 and j < m1:
                        b = 1 + turn2[idx + tstep]
                        if b > best:
                            best = b
                    cur0[idx] = best

        # Initial direction 3: NE, clockwise turn to SE.
        cur2 = [0] * N
        cur0 = [0] * N
        turn0 = straight[0][1]
        turn2 = straight[0][0]
        step = -m + 1
        tstep = m + 1
        for i in ir_asc:
            base = i * m
            for j in jr_desc:
                idx = base + j
                val = flat[idx]
                if val == 2:
                    best = 1
                    if i > 0 and j < m1:
                        b = 1 + cur0[idx + step]
                        if b > best:
                            best = b
                    if i < n1 and j < m1:
                        b = 1 + turn0[idx + tstep]
                        if b > best:
                            best = b
                    cur2[idx] = best
                    if i < n1 and j > 0 and flat[idx - step] == 1:
                        cand = best + 1
                        if cand > ans:
                            ans = cand
                elif val == 0:
                    best = 1
                    if i > 0 and j < m1:
                        b = 1 + cur2[idx + step]
                        if b > best:
                            best = b
                    if i < n1 and j < m1:
                        b = 1 + turn2[idx + tstep]
                        if b > best:
                            best = b
                    cur0[idx] = best

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')
        n = len(s)
        a, b, c = len(A), len(B), len(C)
        total_lit = a + b + c

        # Only "**" can match the empty substring.
        if total_lit == 0:
            return 0

        # Literal blocks cannot overlap, so their total length is a lower bound.
        if total_lit > n:
            return -1

        INF = n + 1

        def kmp_occurrences(pat: str):
            m = len(pat)
            if m == 0 or m > n:
                return []

            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j

            occ = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                if j == m:
                    occ.append(i - m + 1)
                    j = pi[j - 1]
            return occ

        def build_next(occ):
            # nxt[i] = earliest occurrence start >= i, or INF if none.
            nxt = [INF] * (n + 2)
            for pos in occ:
                if pos <= n:
                    nxt[pos] = pos
            for i in range(n - 1, -1, -1):
                if nxt[i + 1] < nxt[i]:
                    nxt[i] = nxt[i + 1]
            return nxt

        if a > 0:
            A_occ = kmp_occurrences(A)
            if not A_occ:
                return -1
        else:
            A_occ = range(n + 1)

        if b > 0:
            B_occ = kmp_occurrences(B)
            if not B_occ:
                return -1
        else:
            B_occ = None

        if c > 0:
            C_occ = kmp_occurrences(C)
            if not C_occ:
                return -1
        else:
            C_occ = None

        # If only one literal block exists, that block itself is optimal.
        if b == 0 and c == 0:
            return a
        if a == 0 and b == 0:
            return c
        if a == 0 and c == 0:
            return b

        nextB = build_next(B_occ) if b > 0 else None
        nextC = build_next(C_occ) if c > 0 else None

        ans = INF

        for start in A_occ:
            left_after_a = start + a

            if b == 0:
                need = left_after_a
            else:
                nb = nextB[left_after_a]
                if nb == INF:
                    continue
                need = nb + b

            if need > n:
                continue

            if c == 0:
                c_start = need
            else:
                c_start = nextC[need]

            if c_start == INF:
                continue

            length = c_start + c - start
            if length < ans:
                ans = length
                if ans == total_lit:
                    return ans

        return -1 if ans == INF else ans

import sys
from math import gcd

CHUNK = 100000


def write_bytes_lines(it, n):
    out = sys.stdout.buffer
    chunk = []
    append = chunk.append
    c = 0
    for _ in range(n):
        append(next(it))
        c += 1
        if c == CHUNK:
            out.write(b"\n".join(chunk))
            out.write(b"\n")
            chunk.clear()
            c = 0
    if c:
        out.write(b"\n".join(chunk))
        out.write(b"\n")


def write_const(g, n):
    out = sys.stdout.buffer
    line = (str(g) + "\n").encode()
    chunk = line * CHUNK
    q, r = divmod(n, CHUNK)
    for _ in range(q):
        out.write(chunk)
    if r:
        out.write(line * r)


def write_mapped(vals, ans):
    out = sys.stdout.buffer
    chunk = []
    append = chunk.append
    c = 0
    for x in vals:
        append(str(ans[x]))
        c += 1
        if c == CHUNK:
            out.write(("\n".join(chunk) + "\n").encode())
            chunk.clear()
            c = 0
    if c:
        out.write(("\n".join(chunk) + "\n").encode())


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    K = int(next(it))

    if K == 1:
        write_bytes_lines(it, N)
        return

    if K == N:
        g = 0
        for x in map(int, it):
            g = gcd(g, x)
        write_const(g, N)
        return

    A = list(map(int, it))
    del data, it

    M = max(A)

    if M == 1:
        write_const(1, N)
        return

    if A.count(A[0]) == N:
        write_const(A[0], N)
        return

    freq = [0] * (M + 1)
    for x in A:
        freq[x] += 1

    ans = [1] * (M + 1)

    f = freq
    a = ans
    k = K
    m1 = M + 1

    m5 = M // 5
    m4 = M // 4
    m3 = M // 3
    m2 = M // 2

    # d with at least 5 multiples: use early stopping when count reaches K.
    for d in range(2, m5 + 1):
        s = f[d]
        if s < k:
            dd = d + d
            for m in range(dd, m1, d):
                s += f[m]
                if s >= k:
                    break

        if s >= k:
            # For very small d, slice assignment is faster in CPython.
            if d <= 100 and d * 10000 <= M:
                a[d:m1:d] = [d] * (M // d)
            else:
                for m in range(d, m1, d):
                    a[m] = d

    # Exactly 4 multiples.
    l = m5 + 1
    if l < 2:
        l = 2
    for d in range(l, m4 + 1):
        d2 = d + d
        d3 = d2 + d
        d4 = d3 + d
        if f[d] + f[d2] + f[d3] + f[d4] >= k:
            a[d] = a[d2] = a[d3] = a[d4] = d

    # Exactly 3 multiples.
    l = m4 + 1
    if l < 2:
        l = 2
    for d in range(l, m3 + 1):
        d2 = d + d
        d3 = d2 + d
        if f[d] + f[d2] + f[d3] >= k:
            a[d] = a[d2] = a[d3] = d

    # Exactly 2 multiples.
    l = m3 + 1
    if l < 2:
        l = 2
    for d in range(l, m2 + 1):
        d2 = d + d
        if f[d] + f[d2] >= k:
            a[d] = a[d2] = d

    # Exactly 1 multiple.
    l = m2 + 1
    if l < 2:
        l = 2
    for d in range(l, m1):
        if f[d] >= k:
            a[d] = d

    del freq, f

    write_mapped(A, ans)


