import sys
from math import gcd, isqrt

MOD = 998244353


def calc(p, arr):
    H_orig = 0
    g = 0
    for a in arr:
        H_orig += a
        g = gcd(g, a)

    if H_orig == 0:
        return 1

    if g > 1:
        q = pow(p, g, MOD)
        H = H_orig // g
        arr = [a // g for a in arr]
    else:
        q = p % MOD
        H = H_orig

    mod = MOD
    H1 = H + 1

    powq = [1] * H1
    for i in range(1, H1):
        powq[i] = (powq[i - 1] * q) % mod

    # dp0[h]: not touched 0 yet, current height h
    # dp1[h]: already touched 0, current height h
    dp0 = powq.copy()
    dp0[0] = 0
    dp1 = [0] * H1
    dp1[0] = 1

    rng = range(1, H1)
    pw = powq
    HH = H

    i = 0
    L = len(arr)
    while i < L:
        a = arr[i]

        if a == 0:
            r = 0
            while i < L and arr[i] == 0:
                r += 1
                i += 1

            if r:
                qr = pow(q, r, mod)
                if qr != 1:
                    factor = 1
                    d0 = dp0
                    d1 = dp1
                    for h in rng:
                        factor = (factor * qr) % mod
                        v = d0[h]
                        if v:
                            d0[h] = (v * factor) % mod
                        v = d1[h]
                        if v:
                            d1[h] = (v * factor) % mod
            continue

        new0 = [0] * H1
        new1 = [0] * H1
        d0 = dp0
        d1 = dp1
        n0 = new0
        n1 = new1
        aa = a

        # target height 0: untouched paths become touched
        s = d0[aa] + d1[aa]
        if s >= mod:
            s -= mod
        n1[0] = s

        for nh in rng:
            idx = nh - aa
            if idx >= 0:
                s0 = d0[idx]
                s1 = d1[idx]
            else:
                s0 = 0
                s1 = 0

            idx = nh + aa
            if idx <= HH:
                s0 += d0[idx]
                if s0 >= mod:
                    s0 -= mod
                s1 += d1[idx]
                if s1 >= mod:
                    s1 -= mod

            if s0 or s1:
                pwn = pw[nh]
                if s0:
                    n0[nh] = (s0 * pwn) % mod
                if s1:
                    n1[nh] = (s1 * pwn) % mod

        dp0 = new0
        dp1 = new1
        i += 1

    return sum(dp1) % mod


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    M = N - 1
    A = data[1:1 + M]

    maxA = max(A) if A else 1
    spf = list(range(maxA + 1))
    if maxA >= 1:
        spf[1] = 1

    for i in range(2, isqrt(maxA) + 1):
        if spf[i] == i:
            for j in range(i * i, maxA + 1, i):
                if spf[j] == j:
                    spf[j] = i

    exp_lists = {}
    for idx, x in enumerate(A):
        while x > 1:
            p = spf[x]
            cnt = 0
            while x % p == 0:
                x //= p
                cnt += 1
            if p not in exp_lists:
                exp_lists[p] = [0] * M
            exp_lists[p][idx] = cnt

    ans = 1
    for p, arr in exp_lists.items():
        if ans == 0:
            break
        ans = (ans * calc(p, arr)) % MOD

    print(ans)


