import sys

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]

    states = 1 << N
    chars = [chr(ord('a') + i) for i in range(26)]

    # Precompute transitions.
    # A state is a bitmask of length N:
    # bit j is 1 iff dp[j+1] > dp[j] in the LCS DP row.
    trans = []
    for mask in range(states):
        old = [0] * (N + 1)
        for j in range(1, N + 1):
            old[j] = old[j - 1] + ((mask >> (j - 1)) & 1)

        row = []
        for c in chars:
            prev = 0
            nxt_mask = 0
            for j in range(1, N + 1):
                if S[j - 1] == c:
                    val = old[j - 1] + 1
                else:
                    val = old[j] if old[j] >= prev else prev

                if val != prev:
                    nxt_mask |= 1 << (j - 1)
                prev = val

            row.append(nxt_mask)
        trans.append(row)

    # DP over strings of length up to M.
    cnt = [0] * states
    cnt[0] = 1

    for _ in range(M):
        nxt = [0] * states
        for mask, val in enumerate(cnt):
            if val:
                for nm in trans[mask]:
                    x = nxt[nm] + val
                    if x >= MOD:
                        x -= MOD
                    nxt[nm] = x
        cnt = nxt

    # Popcount of each mask equals the final LCS length.
    pop = [0] * states
    for i in range(1, states):
        pop[i] = pop[i >> 1] + (i & 1)

    ans = [0] * (N + 1)
    for mask, val in enumerate(cnt):
        if val:
            k = pop[mask]
            x = ans[k] + val
            if x >= MOD:
                x -= MOD
            ans[k] = x

    print(' '.join(map(str, ans)))

