from bisect import bisect_left


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, X = data[0], data[1]
    items = [[] for _ in range(3)]

    p = 2
    for _ in range(N):
        v, a, c = data[p], data[p + 1], data[p + 2]
        p += 3
        items[v - 1].append((c, a))

    # To get a positive minimum, we need at least one food of each vitamin.
    if X < 3 or not items[0] or not items[1] or not items[2]:
        print(0)
        return

    dps = []

    # For each vitamin type, compute dp[c] = maximum vitamin amount
    # obtainable with total calories at most c.
    for typ in range(3):
        dp = [0] * (X + 1)

        for c, a in items[typ]:
            for w in range(X, c - 1, -1):
                nv = dp[w - c] + a
                if nv > dp[w]:
                    dp[w] = nv

        # Ensure dp is nondecreasing (capacity "at most" semantics).
        best = 0
        for i in range(X + 1):
            if dp[i] < best:
                dp[i] = best
            else:
                best = dp[i]

        dps.append(dp)

    upper = min(dps[0][X], dps[1][X], dps[2][X])

    def feasible(k):
        total = 0
        for dp in dps:
            c = bisect_left(dp, k)
            if c > X:
                return False
            total += c
            if total > X:
                return False
        return True

    lo, hi = 0, upper + 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid

    print(lo)


