from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        K = k - 1

        def count_pairs(a: int, b: int) -> int:
            # Count pairs (x, y) with 0 <= x < a, 0 <= y < b, and x + y <= K.
            if K >= a + b - 2:
                return a * b

            m = a - 1
            if m > K:
                m = K

            full_end = K - b + 1
            if full_end > m:
                full_end = m

            res = 0
            if full_end >= 0:
                res = (full_end + 1) * b
                start = full_end + 1
            else:
                start = 0

            if start <= m:
                cnt = m - start + 1
                first = K - start + 1
                last = K - m + 1
                res += cnt * (first + last) // 2

            return res

        total = 0

        # Sum of maximums: assign each subarray to its leftmost maximum.
        next_bound = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            x = nums[i]
            while stack and nums[stack[-1]] <= x:
                stack.pop()
            if stack:
                next_bound[i] = stack[-1]
            stack.append(i)

        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] < x:
                stack.pop()
            prev = stack[-1] if stack else -1
            total += x * count_pairs(i - prev, next_bound[i] - i)
            stack.append(i)

        # Sum of minimums: assign each subarray to its leftmost minimum.
        next_bound = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            x = nums[i]
            while stack and nums[stack[-1]] >= x:
                stack.pop()
            if stack:
                next_bound[i] = stack[-1]
            stack.append(i)

        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] > x:
                stack.pop()
            prev = stack[-1] if stack else -1
            total += x * count_pairs(i - prev, next_bound[i] - i)
            stack.append(i)

        return total

import sys
from operator import mul

_PYPY = sys.implementation.name == 'pypy'


def matmul_dense_loop(A, B, p, n):
    C = [[0] * n for _ in range(n)]
    rng = range(n)
    for i in rng:
        Ai = A[i]
        Ci = C[i]
        for k in rng:
            a = Ai[k]
            if a:
                Bk = B[k]
                for j in rng:
                    Ci[j] += a * Bk[j]
        C[i] = [x % p for x in Ci]
    return C


def matmul(A, B, p, n):
    totalA = 0
    for row in A:
        c = 0
        for v in row:
            if v:
                c += 1
        totalA += c
    if totalA == 0:
        return [[0] * n for _ in range(n)]

    nzB = [0] * n
    totalB = 0
    for i in range(n):
        row = B[i]
        c = 0
        for v in row:
            if v:
                c += 1
        nzB[i] = c
        totalB += c
    if totalB == 0:
        return [[0] * n for _ in range(n)]

    dense_ops = n * n * n
    n2 = n * n

    if _PYPY:
        limit = dense_ops // 2
        product_limit = (n2 * n2) // 2
    else:
        limit = dense_ops // 4
        product_limit = (n2 * n2) // 4
    if limit < 20000:
        limit = 20000

    sd_cost = totalA * n

    if sd_cost <= limit or totalA * totalB <= product_limit:
        Anz = [[(j, v) for j, v in enumerate(A[i]) if v] for i in range(n)]

        cost = 0
        for i in range(n):
            if not Anz[i]:
                continue
            for k, _ in Anz[i]:
                cost += nzB[k]
                if cost > limit:
                    break
            if cost > limit:
                break

        if cost == 0:
            return [[0] * n for _ in range(n)]

        use_ss = cost <= limit and (sd_cost > limit or cost * 3 < sd_cost)

        if use_ss:
            Bnz = [[(j, v) for j, v in enumerate(B[i]) if v] for i in range(n)]
            C = [[0] * n for _ in range(n)]
            for i in range(n):
                Ci = C[i]
                for k, a in Anz[i]:
                    for j, b in Bnz[k]:
                        Ci[j] += a * b
                C[i] = [x % p for x in Ci]
            return C

        if sd_cost <= limit:
            C = [[0] * n for _ in range(n)]
            rng = range(n)
            for i in range(n):
                Ci = C[i]
                for k, a in Anz[i]:
                    Bk = B[k]
                    for j in rng:
                        Ci[j] += a * Bk[j]
                C[i] = [x % p for x in Ci]
            return C

        if cost <= limit:
            Bnz = [[(j, v) for j, v in enumerate(B[i]) if v] for i in range(n)]
            C = [[0] * n for _ in range(n)]
            for i in range(n):
                Ci = C[i]
                for k, a in Anz[i]:
                    for j, b in Bnz[k]:
                        Ci[j] += a * b
                C[i] = [x % p for x in Ci]
            return C

    if _PYPY:
        return matmul_dense_loop(A, B, p, n)

    Bt = list(zip(*B))
    m = mul
    return [[sum(map(m, Ai, col)) % p for col in Bt] for Ai in A]


def mat_pow(A, e, p, n):
    # e is odd and >= 3 here
    result = A
    base = A
    e >>= 1
    while e:
        base = matmul(base, base, p, n)
        if e & 1:
            result = matmul(result, base, p, n)
        e >>= 1
    return result


def is_diagonal(A, n):
    for i in range(n):
        row = A[i]
        for j in range(n):
            if i != j and row[j] != 0:
                return False
    return True


