            if v == 0:
                K += 1

    if is_diagonal(A, N):
        T = [row[:] for row in A]
    else:
        T = mat_pow(A, p, p, N)

    if p == 3:
        for i in range(N):
            for j in range(N):
                if A[i][j] == 0:
                    if i == j:
                        Ai = A[i]
                        Ti = T[i]
                        for k in range(N):
                            Ti[k] += Ai[k]
                        for r in range(N):
                            T[r][i] += A[r][i]
