from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        if not nums:
            return 0

        n = len(nums)
        prefix = [0] * (n + 1)
        neg_pos = {}

        cur = 0
        best = -10**30

        for i, a in enumerate(nums, 1):
            prefix[i] = prefix[i - 1] + a

            if cur < 0:
                cur = a
            else:
                cur += a
            if cur > best:
                best = cur

            if a < 0:
                if a in neg_pos:
                    neg_pos[a].append(i)
                else:
                    neg_pos[a] = [i]

        # If there is no positive element, deleting negatives cannot create one.
        if best <= 0:
            return best

        if not neg_pos:
            return best

        N = n + 1

        # pref_min[i] = min(prefix[0..i])
        pref_min = [0] * N
        mn = prefix[0]
        for i in range(N):
            v = prefix[i]
            if v < mn:
                mn = v
            pref_min[i] = mn

        # suff_max[i] = max(prefix[i..n])
        suff_max = [0] * N
        mx = prefix[n]
        for i in range(n, -1, -1):
            v = prefix[i]
            if v > mx:
                mx = v
            suff_max[i] = mx

        global_min = pref_min[n]
        global_max = suff_max[0]
        ans = best

        multi = []

        # Values occurring once can be handled in O(1).
        for x, pos in neg_pos.items():
            m = len(pos)
            y = -x
            if m == 1:
                if global_max + y - global_min > ans:
                    p = pos[0]
                    cand = suff_max[p] + y - pref_min[p - 1]
                    if cand > ans:
                        ans = cand
            else:
                multi.append((x, pos))

        if not multi:
            return ans

        # Keep only values that can theoretically improve the answer.
        multi = [
            (x, pos)
            for x, pos in multi
            if global_max + (-x) * len(pos) - global_min > ans
        ]

        if not multi:
            return ans

        del neg_pos

        # Segment tree for range min/max queries on prefix sums.
        INF = 10**30
        NEG_INF = -INF

        size = 1
        while size < N:
            size <<= 1

        minv = [INF] * (2 * size)
        maxv = [NEG_INF] * (2 * size)

        base = size
        for i, v in enumerate(prefix):
            minv[base + i] = v
            maxv[base + i] = v

        for i in range(size - 1, 0, -1):
            l = i << 1
            r = l | 1
            minv[i] = minv[l] if minv[l] < minv[r] else minv[r]
            maxv[i] = maxv[l] if maxv[l] > maxv[r] else maxv[r]

        def query(l, r, minv=minv, maxv=maxv, size=size, INF=INF, NEG_INF=NEG_INF):
            l += size
            r += size
            mn = INF
            mx = NEG_INF

            while l <= r:
                if l & 1:
                    v = minv[l]
                    if v < mn:
                        mn = v
                    v = maxv[l]
                    if v > mx:
                        mx = v
                    l += 1

                if not (r & 1):
                    v = minv[r]
                    if v < mn:
                        mn = v
                    v = maxv[r]
                    if v > mx:
                        mx = v
                    r -= 1

                l >>= 1
                r >>= 1

            return mn, mx

        # Process values occurring multiple times.
        for x, pos in multi:
            m = len(pos)
            y = -x

            if global_max + y * m - global_min <= ans:
                continue

            # First interval before the first occurrence: count = 0.
            min_val = pref_min[pos[0] - 1]

            add = y  # y * current_count, starting from count = 1 for internal intervals.

            for idx in range(1, m):
                L = pos[idx - 1]
                R = pos[idx] - 1

                if L == R:
                    mn = prefix[L]
                    mx = mn
                elif R == L + 1:
                    a = prefix[L]
                    b = prefix[R]
                    if a < b:
                        mn, mx = a, b
                    else:
                        mn, mx = b, a
                else:
                    mn, mx = query(L, R)

                cand = mx + add - min_val
                if cand > ans:
                    ans = cand

                val = mn + add
                if val < min_val:
                    min_val = val

                add += y

            # Last interval after the last occurrence: count = m.
            mx = suff_max[pos[-1]]
            cand = mx + add - min_val
            if cand > ans:
                ans = cand

        return ans

import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    A = [x - 1 for x in data[2:2 + N]]

    indeg = [0] * N
    for a in A:
        indeg[a] += 1

    q = [i for i, d in enumerate(indeg) if d == 0]
    head = 0
    in_cycle = [True] * N

    while head < len(q):
        v = q[head]
        head += 1
        in_cycle[v] = False
        p = A[v]
        indeg[p] -= 1
        if indeg[p] == 0:
            q.append(p)

    order = q

    children = [[] for _ in range(N)]
    for u in range(N):
        if not in_cycle[u]:
            children[A[u]].append(u)

    M1 = M + 1
    rng = range(1, M1)
    mod = MOD

    leaf_H = [i % mod for i in range(M1)]
    H = [None] * N

    for v in order:
        ch = children[v]

        if not ch:
            H[v] = leaf_H

        elif len(ch) == 1:
            u = ch[0]
            hv = H[u][:]
            H[u] = None

            s = 0
            for c in rng:
                s += hv[c]
                if s >= mod:
                    s -= mod
                hv[c] = s

            H[v] = hv

        else:
            u0 = ch[0]
            prod = H[u0][:]
            H[u0] = None

            for u in ch[1:]:
                arr = H[u]
                for c in rng:
                    prod[c] = (prod[c] * arr[c]) % mod
                H[u] = None

            s = 0
            for c in rng:
                s += prod[c]
                if s >= mod:
                    s -= mod
                prod[c] = s

            H[v] = prod

        children[v] = None

    ans = 1
    visited = [False] * N

    for i in range(N):
        if in_cycle[i] and not visited[i]:
            cyc = []
            v = i
            while not visited[v]:
                visited[v] = True
                cyc.append(v)
                v = A[v]

            comp = None

            for r in cyc:
                ch = children[r]
                if ch:
                    for u in ch:
                        arr = H[u]
                        if comp is None:
                            comp = arr[:]
                        else:
                            for c in rng:
                                comp[c] = (comp[c] * arr[c]) % mod
                        H[u] = None
                children[r] = None

            if comp is None:
                total = M % mod
            else:
                total = 0
                for c in rng:
                    total += comp[c]
                    if total >= mod:
                        total -= mod

            ans = (ans * total) % mod

    print(ans)


if __name__ == "__main__":
    main()

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7
        N = n - 1

        if k < 0 or k > N:
            return 0

        fact = [1] * (N + 1)
        for i in range(1, N + 1):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact = [1] * (N + 1)
        inv_fact[N] = pow(fact[N], MOD - 2, MOD)
        for i in range(N, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        comb = fact[N] * inv_fact[k] % MOD * inv_fact[N - k] % MOD
        return comb * (m % MOD) % MOD * pow((m - 1) % MOD, N - k, MOD) % MOD

