def solve():
    input = sys.stdin.buffer.readline
    first = input().split()
    if not first:
        return

    N = int(first[0])
    M = int(first[1])

    # For each constrained row:
    # L = minimum required black prefix length (from black cells)
    # U = maximum allowed black prefix length (from white cells)
    rows = {}

    for _ in range(M):
        x_b, y_b, c = input().split()
        x = int(x_b)
        y = int(y_b)

        L, U = rows.get(x, (0, N))

        if c == b'B':
            if y > L:
                L = y
        else:
            u = y - 1
            if u < U:
                U = u

        rows[x] = (L, U)

    min_u = N

    for x in sorted(rows):
        L, U = rows[x]

        # The row itself must be possible.
        if L > U:
            print("No")
            return

        # Since row prefix lengths must be non-increasing,
        # this row's lower bound cannot exceed the smallest upper bound above it.
        if L > min_u:
            print("No")
            return

        if U < min_u:
            min_u = U

    print("Yes")

