import sys


def solve():
    data = sys.stdin.buffer.read().split()
    if len(data) < 3:
        return

    K = int(data[0])
    S = data[1]
    T = data[2]
    n = len(S)
    m = len(T)

    if abs(n - m) > K:
        print("No")
        return

    if S == T:
        print("Yes")
        return

    # Always possible by substituting min(n,m) characters and inserting/deleting the rest.
    if K >= max(n, m):
        print("Yes")
        return

    # Exact LCP queries using memoryview equality.
    try:
        use_mv = (memoryview(b"a")[0:1] == memoryview(b"a")[0:1])
    except Exception:
        use_mv = False

    mvS = memoryview(S)
    mvT = memoryview(T)

    if use_mv:
        def lcp(x, y, S=S, T=T, mvS=mvS, mvT=mvT, n=n, m=m):
            max_len = n - x
            t = m - y
            if t < max_len:
                max_len = t
            if max_len <= 0:
                return 0
            if S[x] != T[y]:
                return 0

            # Small lengths are faster with a direct loop.
            if max_len <= 64:
                i = 1
                while i < max_len and S[x + i] == T[y + i]:
                    i += 1
                return i

            # Exponential search, then binary search.
            step = 1
            while step < max_len:
                nxt = step << 1
                if nxt > max_len:
                    nxt = max_len
                if mvS[x:x + nxt] == mvT[y:y + nxt]:
                    step = nxt
                    if step == max_len:
                        return max_len
                else:
                    break

            low = step
            high = nxt
            while low + 1 < high:
                mid = (low + high) >> 1
                if mvS[x:x + mid] == mvT[y:y + mid]:
                    low = mid
                else:
                    high = mid
            return low
    else:
        def lcp(x, y, S=S, T=T, n=n, m=m):
            max_len = n - x
            t = m - y
            if t < max_len:
                max_len = t
            i = 0
            while i < max_len and S[x + i] == T[y + i]:
                i += 1
            return i

    # Landau-Vishkin style furthest-reaching DP for edit distance <= K.
    # Diagonal k = x - y, where x is consumed length of S and y of T.
    W = 2 * K + 3
    off = K + 1
    NEG = -1

    prev = [NEG] * W
    x0 = lcp(0, 0)
    prev[off] = x0

    if n == m and x0 == n:
        print("Yes")
        return

    for e in range(1, K + 1):
        curr = [NEG] * W

        k_min = -e
        if k_min < -m:
            k_min = -m
        k_max = e
        if k_max > n:
            k_max = n

        for k in range(k_min, k_max + 1):
            idx = off + k

            # Valid x-range on diagonal k:
            # x >= 0, y = x-k >= 0, x <= n, y <= m
            lo = k if k > 0 else 0
            hi = n
            mk = m + k
            if mk < hi:
                hi = mk
            if lo > hi:
                continue

            old = prev[idx]

            # Already at the end of this diagonal; no further free extension is possible.
            if old == hi:
                curr[idx] = old
                if old == n and old - k == m:
                    print("Yes")
                    return
                continue

            best = old

            # Delete one character from S: from diagonal k-1.
            v = prev[idx - 1]
            if v != NEG:
                x = v + 1
                if lo <= x <= hi and x > best:
                    best = x

            # Insert one character into S: from diagonal k+1.
            v = prev[idx + 1]
            if v != NEG:
                x = v
                if lo <= x <= hi and x > best:
                    best = x

            # Substitute one character: from the same diagonal.
            if old != NEG:
                x = old + 1
                if lo <= x <= hi and x > best:
                    best = x

            if best == NEG:
                continue

            # Extend by matching characters for free.
            if best != old:
                y = best - k
                if best < n and y < m:
                    best += lcp(best, y)

            curr[idx] = best

            if best == n and best - k == m:
                print("Yes")
                return

        prev = curr

    final_k = n - m
    if abs(final_k) <= K and prev[off + final_k] == n:
        print("Yes")
    else:
        print("No")


if __name__ == "__main__":
    solve()
